<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $money=static fn(float$value):string=>'R$ '.number_format($value,2,',','.'); ?>
<div class="actions"><div><span class="status">Financeiro · <?= $escape($customer['unit_name']) ?></span><h1>Gerar checkout</h1><p class="meta">Cliente: <strong><?= $escape($customer['name']) ?></strong></p></div><a href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$customer['id'] ?>">Cancelar</a></div>
<?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?> <a href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$customer['id'] ?>/edit">Editar cliente</a></p><?php endif;?><?php if(!$writeEnabled):?><p class="alert alert-warning"><strong>Modo seguro:</strong> a criação real de checkout está desativada.</p><?php endif;?>
<section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/finance/customers/<?= (int)$customer['id'] ?>/checkouts"><?= $csrfField ?><div class="form-field"><label for="checkout-product">Curso e preço <span class="required">*</span></label><select id="checkout-product" name="product_id" required><option value="">Selecione</option><?php foreach($products as$product):?><option value="<?= (int)$product['id'] ?>"><?= $escape($product['name']) ?> · <?= $escape($money((float)$product['value'])) ?> · <?= str_replace(['PIX','CREDIT_CARD'],['Pix','Cartão'],(string)$product['billing_types']) ?></option><?php endforeach;?></select><?php if($products===[]):?><small>Não existe curso ativo para esta unidade. Cadastre-o em ADM → Cursos e preços.</small><?php endif;?></div><div class="alert alert-warning"><strong>Checkout avulso:</strong> o Asaas receberá os dados do cliente e cuidará do Pix ou cartão. O retorno da tela não confirma pagamento; a situação será atualizada pelo webhook.</div><label class="check-option"><input type="checkbox" name="confirm_checkout" value="1" required> Conferi cliente, unidade, curso e preço.</label><div class="form-actions"><button class="button-primary" type="submit"<?= !$writeEnabled||$products===[]?' disabled':'' ?>><i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i> Gerar link de checkout</button></div></form></div></section>
